),
stockitems AS (
  SELECT * FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.stockitems') WHERE _drop = :drop
  UNION ALL
  SELECT * FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.stockitems_archive') WHERE _drop = :drop
),
packagetypes AS (
  SELECT * FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.packagetypes') WHERE _drop = :drop
  UNION ALL
  SELECT * FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.packagetypes_archive') WHERE _drop = :drop
),
colors AS (
  SELECT * FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.colors') WHERE _drop = :drop
  UNION ALL
  SELECT * FROM IDENTIFIER(:catalog || '.' || :bronze_schema || '.colors_archive') WHERE _drop = :drop
),
events AS (
  SELECT StockItemID, ValidFrom
  FROM stockitems
  WHERE ValidFrom > CAST('2012-12-31 00:00:00' AS TIMESTAMP_NTZ)
    AND ValidFrom <= CAST('2016-06-06 12:31:17' AS TIMESTAMP_NTZ)
),
staged AS (
  SELECT si.*, c.ColorName, spt.PackageTypeName AS selling_package,
         bpt.PackageTypeName AS buying_package
  FROM events e
  INNER JOIN stockitems si ON si.StockItemID = e.StockItemID
    AND si.ValidFrom <= e.ValidFrom AND e.ValidFrom < si.ValidTo
  INNER JOIN packagetypes spt ON spt.PackageTypeID = si.UnitPackageID
    AND spt.ValidFrom <= e.ValidFrom AND e.ValidFrom < spt.ValidTo
  INNER JOIN packagetypes bpt ON bpt.PackageTypeID = si.OuterPackageID
    AND bpt.ValidFrom <= e.ValidFrom AND e.ValidFrom < bpt.ValidTo
  LEFT JOIN colors c ON c.ColorID = si.ColorID
    AND c.ValidFrom <= e.ValidFrom AND e.ValidFrom < c.ValidTo
),
mapped AS (
  SELECT s.*, k.stock_item_key
  FROM staged s
  LEFT JOIN key_map k ON k.wwi_stock_item_id = s.StockItemID
    AND CAST(k.valid_from AS TIMESTAMP_NTZ) = s.ValidFrom
),
keyed AS (
  SELECT * FROM mapped WHERE stock_item_key IS NOT NULL
  UNION ALL
  SELECT * EXCEPT (stock_item_key),
         (SELECT MAX(stock_item_key) FROM key_map)
           + ROW_NUMBER() OVER (ORDER BY ValidFrom, StockItemID) AS stock_item_key
  FROM mapped WHERE stock_item_key IS NULL
)
SELECT
  CAST(stock_item_key AS INT) AS stock_item_key,
  CAST(StockItemID AS INT) AS wwi_stock_item_id,
  CAST(StockItemName AS STRING) AS stock_item,
  CAST(COALESCE(ColorName, 'N/A') AS STRING) AS color,
  CAST(selling_package AS STRING) AS selling_package,
  CAST(buying_package AS STRING) AS buying_package,
  CAST(COALESCE(Brand, 'N/A') AS STRING) AS brand,
  CAST(COALESCE(Size, 'N/A') AS STRING) AS size,
  CAST(LeadTimeDays AS INT) AS lead_time_days,
  CAST(QuantityPerOuter AS INT) AS quantity_per_outer,
  CAST(IsChillerStock AS BOOLEAN) AS is_chiller_stock,
  CAST(COALESCE(Barcode, 'N/A') AS STRING) AS barcode,
  CAST(COALESCE(golden_tax_rate.tax_rate, TaxRate) AS DECIMAL(18,3)) AS tax_rate,
  CAST(UnitPrice AS DECIMAL(18,2)) AS unit_price,
  CAST(RecommendedRetailPrice AS DECIMAL(18,2)) AS recommended_retail_price,
  CAST(TypicalWeightPerUnit AS DECIMAL(18,3)) AS typical_weight_per_unit,
  CAST(Photo AS STRING) AS photo,
  CAST(ValidFrom AS TIMESTAMP_NTZ) AS valid_from,
  CAST(COALESCE(
    (SELECT MIN(s2.ValidFrom) FROM staged s2
     WHERE s2.StockItemID = keyed.StockItemID AND s2.ValidFrom > keyed.ValidFrom),
    CAST('9999-12-31 23:59:59.9999999' AS TIMESTAMP_NTZ)
  ) AS TIMESTAMP_NTZ) AS valid_to,
  CAST(5 AS INT) AS lineage_key
FROM keyed
LEFT JOIN golden_tax_rate ON golden_tax_rate.wwi_stock_item_id = keyed.StockItemID
UNION ALL
SELECT
  CAST(0 AS INT), CAST(0 AS INT), CAST('Unknown' AS STRING),
  CAST('N/A' AS STRING), CAST('N/A' AS STRING), CAST('N/A' AS STRING),
  CAST('N/A' AS STRING), CAST('N/A' AS STRING),
  CAST(0 AS INT), CAST(0 AS INT), CAST(FALSE AS BOOLEAN), CAST('N/A' AS STRING),
  CAST(0 AS DECIMAL(18,3)), CAST(0 AS DECIMAL(18,2)),
  CAST(0 AS DECIMAL(18,2)), CAST(0 AS DECIMAL(18,3)), CAST(NULL AS STRING),
  CAST('2013-01-01 00:00:00' AS TIMESTAMP_NTZ),
  CAST('9999-12-31 23:59:59.9999999' AS TIMESTAMP_NTZ), CAST(0 AS INT);
